//! Data-only final-encoder byte paging. Cursors/hashes are not source authority;
//! concrete providers must still validate their actual pinned frame every time.
use std::io::{self,Write};use serde::{Serialize,Deserialize};
pub const MAX_FRAGMENT:usize=super::MAX_OUTPUT/8;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct OutputId(pub(crate) u128);
impl Serialize for OutputId{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut out=[b'0';32];for(i,byte)in out.iter_mut().enumerate(){*byte=b"0123456789abcdef"[((self.0>>((31-i)*4))&15)as usize];}s.serialize_str(std::str::from_utf8(&out).unwrap())}}
impl<'de>Deserialize<'de>for OutputId{fn deserialize<D:serde::Deserializer<'de>>(d:D)->Result<Self,D::Error>{struct Id;impl serde::de::Visitor<'_>for Id{type Value=OutputId;fn expecting(&self,f:&mut std::fmt::Formatter)->std::fmt::Result{f.write_str("32 hexadecimal final-output digits")}fn visit_str<E:serde::de::Error>(self,value:&str)->Result<OutputId,E>{if value.len()!=32||!value.bytes().all(|b|b.is_ascii_hexdigit()){return Err(E::custom("invalid final-output id"))}u128::from_str_radix(value,16).map(OutputId).map_err(E::custom)}}d.deserialize_str(Id)}}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct ByteCursor{pub output_id:OutputId,pub total:u64,pub offset:u64}
impl ByteCursor{pub fn validate(&self,maximum:u64)->io::Result<()>{if self.total==0||self.total>maximum||self.offset==0||self.offset>=self.total{return Err(io::Error::new(io::ErrorKind::InvalidInput,"byte continuation cursor outside bounded output"))}Ok(())}}
pub(crate) trait Buffer{fn append(&mut self,bytes:&[u8])->io::Result<()>;fn bytes(&self)->&[u8];}
#[derive(Clone,Copy,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Fragment{pub output_id:OutputId,pub offset:u64,pub length:u32,pub total:u64,pub next:Option<ByteCursor>,pub end_of_output:bool}
pub(crate) struct Collector<'a>{buffer:&'a mut dyn Buffer,cursor:Option<ByteCursor>,limit:usize,total:u64,hash:xxhash_rust::xxh3::Xxh3,maximum:u64}
impl<'a>Collector<'a>{pub(crate) fn new(buffer:&'a mut dyn Buffer,cursor:Option<ByteCursor>,limit:usize,maximum:u64)->io::Result<Self>{if limit==0||limit>MAX_FRAGMENT||!buffer.bytes().is_empty(){return Err(io::Error::new(io::ErrorKind::InvalidInput,"byte fragment buffer/limit invalid"))}if let Some(cursor)=cursor{cursor.validate(maximum)?;}Ok(Self{buffer,cursor,limit,total:0,hash:xxhash_rust::xxh3::Xxh3::new(),maximum})}pub(crate) fn finish(self)->io::Result<Fragment>{crate::daemon::control::checkpoint()?;let id=OutputId(self.hash.digest128());let offset=self.cursor.map_or(0,|cursor|cursor.offset);if self.cursor.is_some_and(|cursor|cursor.output_id!=id||cursor.total!=self.total)||offset>self.total{return Err(io::Error::new(io::ErrorKind::InvalidInput,"encoded output changed or cursor belongs to another output"))}let expected=(self.total-offset).min(self.limit as u64)as usize;if self.buffer.bytes().len()!=expected{return Err(io::Error::new(io::ErrorKind::InvalidData,"encoded fragment length differs"))}let end=offset.checked_add(expected as u64).ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"byte fragment offset overflow"))?;Ok(Fragment{output_id:id,offset,length:expected as u32,total:self.total,next:(end<self.total).then_some(ByteCursor{output_id:id,total:self.total,offset:end}),end_of_output:end==self.total})}}
impl Write for Collector<'_>{fn write(&mut self,bytes:&[u8])->io::Result<usize>{let offset=self.cursor.map_or(0,|cursor|cursor.offset);let requested_end=offset.checked_add(self.limit as u64).ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"byte range overflow"))?;for chunk in bytes.chunks(MAX_FRAGMENT){crate::daemon::control::checkpoint()?;let end=self.total.checked_add(chunk.len()as u64).filter(|n|*n<=self.maximum).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"encoded output exceeds existing allowance"))?;self.hash.update(chunk);let first=offset.max(self.total);let last=requested_end.min(end);if first<last{self.buffer.append(&chunk[(first-self.total)as usize..(last-self.total)as usize])?;}self.total=end;}Ok(bytes.len())}fn flush(&mut self)->io::Result<()>{crate::daemon::control::checkpoint()}}
/// Incremental data continuity only. A concrete client must validate matching
/// source/configuration pins before passing a fragment. No full-result success
/// is reported until all bytes and the complete encoded hash agree.
/// `accept` writes unverified prefixes to a caller-funded STAGING sink only.
/// A concrete client must validate every page's source/configuration pins, then
/// call `finish`, revalidate its final pinned frame, and only then publish or
/// install staged bytes. Never pass a public output/install sink to `accept`.
pub struct Continuity{id:Option<OutputId>,total:u64,accepted:u64,hash:xxhash_rust::xxh3::Xxh3,complete:bool,failed:bool,maximum:u64}
impl Continuity{pub fn new(maximum:u64)->Self{Self{id:None,total:0,accepted:0,hash:xxhash_rust::xxh3::Xxh3::new(),complete:false,failed:false,maximum}}}
impl Continuity{pub fn is_complete(&self)->bool{self.complete&&!self.failed}pub fn accept(&mut self,meta:Fragment,bytes:&[u8],staging:&mut impl Write)->io::Result<Option<ByteCursor>>{if self.failed||self.complete{return Err(io::Error::new(io::ErrorKind::InvalidInput,"byte sequence already stopped"))}let result=(||{crate::daemon::control::checkpoint()?;let next=meta.offset.checked_add(bytes.len()as u64).filter(|n|*n<=meta.total).ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"fragment range overflow"))?;let expected_next=(next<meta.total).then_some(ByteCursor{output_id:meta.output_id,total:meta.total,offset:next});if meta.total>self.maximum||bytes.len()>MAX_FRAGMENT||meta.length as usize!=bytes.len()||meta.offset!=self.accepted||meta.end_of_output!=(next==meta.total)||meta.next!=expected_next||self.id.is_some_and(|id|id!=meta.output_id||self.total!=meta.total)||(!meta.end_of_output&&bytes.is_empty()){return Err(io::Error::new(io::ErrorKind::InvalidData,"byte fragment identity, gap, total or completion differs"))}self.hash.update(bytes);if meta.end_of_output&&self.hash.digest128()!=meta.output_id.0{return Err(io::Error::new(io::ErrorKind::InvalidData,"complete encoded output hash differs"))}crate::daemon::control::checkpoint()?;staging.write_all(bytes)?;self.id=Some(meta.output_id);self.total=meta.total;self.accepted=next;self.complete=meta.end_of_output;Ok(meta.next)})();if result.is_err(){self.failed=true;}result}pub fn finish(&self)->io::Result<()>{if self.is_complete(){Ok(())}else{Err(io::Error::new(io::ErrorKind::InvalidData,"encoded output remains incomplete"))}}}

